package com.huy.enterprise.order;
import java.math.BigDecimal; import java.time.*; import java.util.*; import com.huy.enterprise.common.enums.PurchaseOrderStatus;
public record PurchaseOrderResponse(UUID id,String orderCode,UUID supplierId,String supplierName,LocalDate orderDate,LocalDate expectedDeliveryDate,PurchaseOrderStatus status,BigDecimal totalAmount,String notes,List<PurchaseOrderItemResponse> items,OffsetDateTime createdAt,OffsetDateTime updatedAt){static PurchaseOrderResponse from(PurchaseOrder o){return new PurchaseOrderResponse(o.getId(),o.getOrderCode(),o.getSupplier().getId(),o.getSupplier().getName(),o.getOrderDate(),o.getExpectedDeliveryDate(),o.getStatus(),o.getTotalAmount(),o.getNotes(),o.getItems().stream().map(PurchaseOrderItemResponse::from).toList(),o.getCreatedAt(),o.getUpdatedAt());}}
